def test_AnsibleJ2Vars___getitem__():
    import pytest

    class UnsafeValue(object):
        __UNSAFE__ = True

    class FakeTemplar(object):
        def __init__(self):
            self.available_variables = {
                'normal': '{{ value }}',
                'vars': {'answer': 42},
                'unsafe': UnsafeValue(),
                'undefined': '{{ undefined }}',
                'broken': '{{ broken }}',
                'item': 'available-value',
            }
            self.template_calls = []

        def template(self, value):
            self.template_calls.append(value)

            if value == '{{ undefined }}':
                error = AnsibleUndefinedVariable('inner variable is undefined')
                if not hasattr(error, 'message'):
                    error.message = to_native(error)
                raise error

            if value == '{{ broken }}':
                raise RuntimeError('templating failed')

            return 'templated:%s' % value

    templar = FakeTemplar()
    global_value = object()

    variables = AnsibleJ2Vars(
        templar,
        {
            'global_only': global_value,
            'normal': 'global-value',
            'item': 'global-value',
        },
        locals={
            'l_item': 'local-value',
        },
    )

    # Locals have the highest precedence and are returned without templating.
    assert variables['item'] == 'local-value

