def test_AnsibleJ2Vars___getitem__():
    class FakeTemplar(object):
        def __init__(self):
            self.available_variables = {
                'templated': 'source',
                'available_over_global': 'available',
                'vars': {'raw': '{{ value }}'},
            }
            self.template_calls = []

        def template(self, value):
            self.template_calls.append(value)
            return 'templated:%s' % value

    templar = FakeTemplar()
    globals_ = {
        'global_only': 'global',
        'available_over_global': 'global',
    }
    locals_ = {
        'local_only': 'local',
        'templated': 'local override',
    }

    variables = AnsibleJ2Vars(templar, globals_, locals_)

    # Locals have the highest precedence and are returned without templating.
    assert variables['local_only'] == 'local'
    assert variables['templated'] == 'local override'

    # Available variables take precedence over globals and are templated.
    assert variables['available_over_global'] == 'templated:available'

    # Globals are returned directly.
    assert variables['global_only'] == 'global'

    # The special "vars" mapping must not be templated.
    raw_vars = templar.available_variables['vars']
    assert variables['vars'] is raw_vars

    assert templar.template_calls == ['available']

    try:
        variables['undefined']
    except KeyError as exc:
        assert 'undefined variable: undefined' in str(exc)
    else:
        raise AssertionError('Accessing an undefined variable did not raise KeyError')
